/**
 * Writes worker/wrangler.practice.toml: a generated copy of wrangler.toml for
 * the practice shop on this machine, and nothing else.
 *
 * Why it exists: the worker now refuses every request (503
 * shared_allowance_paused) unless the shared allowance governor, a durable
 * object that lives in the separate i64os-quota-guard script, answers. That
 * script is not running locally. So the practice copy drops that one binding
 * and sets SHARED_ALLOWANCE_REQUIRED to "false".
 *
 * What it never does: edit the committed wrangler.toml, or touch the deploy
 * path. The generated file is gitignored and `wrangler deploy` never reads it.
 * The generated file also names the same database, so the practice API uses the
 * same local database as `npm run sandbox`.
 *
 * Also makes sure worker/.dev.vars exists (a throwaway JWT_SECRET only) so the
 * practice API starts without Infisical. An existing .dev.vars is left alone.
 *
 * Run via: npm run practice:config  (from worker/); `npm run practice` runs it.
 */
import { randomBytes } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const WORKER = join(dirname(fileURLToPath(import.meta.url)), '..');
export const PRACTICE_CONFIG = join(WORKER, 'wrangler.practice.toml');

/** Pure, so the test can run it on a string. */
export function practiceToml(source) {
  const blocks = source.split(/(?=^\[\[?[A-Za-z_.]+\]\]?\s*$)/m);
  let removed = 0;
  const kept = blocks.filter((block) => {
    const drop = /^\[\[durable_objects\.bindings\]\]/m.test(block) && /name\s*=\s*"SHARED_ALLOWANCE"/.test(block);
    if (drop) removed += 1;
    return !drop;
  });
  if (removed !== 1) throw new Error(`Expected one SHARED_ALLOWANCE binding in wrangler.toml, found ${removed}.`);
  let out = kept.join('');
  const before = out;
  out = out.replace(/^SHARED_ALLOWANCE_REQUIRED\s*=\s*"true"/m, 'SHARED_ALLOWANCE_REQUIRED = "false"');
  if (out === before) throw new Error('SHARED_ALLOWANCE_REQUIRED = "true" not found in wrangler.toml.');
  return `# GENERATED by sandbox/practice-config.mjs. Do not edit, do not commit, never deploy.\n${out}`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(PRACTICE_CONFIG, practiceToml(readFileSync(join(WORKER, 'wrangler.toml'), 'utf8')));
  const vars = join(WORKER, '.dev.vars');
  if (!existsSync(vars)) {
    writeFileSync(vars, `JWT_SECRET=${randomBytes(32).toString('hex')}\n`, { mode: 0o600 });
    console.log('Wrote a throwaway worker/.dev.vars (JWT_SECRET only).');
  }
  console.log('Wrote worker/wrangler.practice.toml (no shared allowance binding).');
}
